#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);

typedef unsigned __int128 u128;

typedef struct { uint64_t r0,r1,r2,s1,s2,h0,h1,h2; } poly_t;

static void poly_init(poly_t *p, const unsigned char *key){
    uint64_t t0,t1; memcpy(&t0,key,8); memcpy(&t1,key+8,8);
    p->r0 = t0 & 0xffc0fffffffULL;
    p->r1 = ((t0>>44)|(t1<<20)) & 0xfffffc0ffffULL;
    p->r2 = (t1>>24) & 0x00ffffffc0fULL;
    p->s1 = p->r1*(5<<2); p->s2 = p->r2*(5<<2);
    p->h0=p->h1=p->h2=0;
}
static void poly_blocks(poly_t *p, const unsigned char *m, size_t bytes){
    const uint64_t hibit = 1ULL<<40;
    uint64_t r0=p->r0,r1=p->r1,r2=p->r2,s1=p->s1,s2=p->s2,h0=p->h0,h1=p->h1,h2=p->h2;
    while(bytes>=16){
        uint64_t t0,t1; memcpy(&t0,m,8); memcpy(&t1,m+8,8);
        h0 += t0 & 0xfffffffffffULL;
        h1 += ((t0>>44)|(t1<<20)) & 0xfffffffffffULL;
        h2 += (((t1>>24)) & 0x3ffffffffffULL) | hibit;
        u128 d0 = (u128)h0*r0 + (u128)h1*s2 + (u128)h2*s1;
        u128 d1 = (u128)h0*r1 + (u128)h1*r0 + (u128)h2*s2;
        u128 d2 = (u128)h0*r2 + (u128)h1*r1 + (u128)h2*r0;
        uint64_t c;
        c = (uint64_t)(d0>>44); h0 = (uint64_t)d0 & 0xfffffffffffULL;
        d1 += c; c = (uint64_t)(d1>>44); h1 = (uint64_t)d1 & 0xfffffffffffULL;
        d2 += c; c = (uint64_t)(d2>>42); h2 = (uint64_t)d2 & 0x3ffffffffffULL;
        h0 += c*5; c = h0>>44; h0 &= 0xfffffffffffULL;
        h1 += c;
        m+=16; bytes-=16;
    }
    p->h0=h0;p->h1=h1;p->h2=h2;
}

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    unsigned int key[8]; unsigned int ctr[4];
    const unsigned char *rkey;
    uint64_t h[3];
} job_t;

#define SUB (16*1024)
static void *worker(void *arg){
    job_t *j=(job_t*)arg;
    poly_t p; poly_init(&p, j->rkey);
    unsigned int ctr[4]; memcpy(ctr,j->ctr,16);
    size_t off=0;
    while(off<j->len){
        size_t n = j->len-off; if(n>SUB) n=SUB;
        ChaCha20_ctr32(j->out+off, j->in+off, n, j->key, ctr);
        size_t full = n & ~(size_t)15;
        poly_blocks(&p, j->out+off, full);
        if(full<n){
            unsigned char buf[16]={0}; memcpy(buf,j->out+off+full,n-full);
            poly_blocks(&p, buf, 16);
        }
        ctr[0] += (unsigned int)(n/64);
        off+=n;
    }
    j->h[0]=p.h0; j->h[1]=p.h1; j->h[2]=p.h2;
    return NULL;
}

/* encrypt(key, nonce, plaintext, nthreads) -> (ciphertext, polykey32, [(h0,h1,h2,nblocks),...]) */
static PyObject *encrypt(PyObject *self, PyObject *args){
    Py_buffer kb, nb, pb; int nth;
    if(!PyArg_ParseTuple(args,"y*y*y*i",&kb,&nb,&pb,&nth)) return NULL;
    size_t len = pb.len;
    unsigned int key[8], ctr[4];
    memcpy(key,kb.buf,32); ctr[0]=0; memcpy(ctr+1,nb.buf,12);
    unsigned char zero[64]={0}, blk0[64];
    ChaCha20_ctr32(blk0, zero, 64, key, ctr);
    PyObject *ct = PyBytes_FromStringAndSize(NULL, len);
    if(!ct){PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);return NULL;}
    unsigned char *out=(unsigned char*)PyBytes_AS_STRING(ct);
    if(nth<1) nth=1; if(nth>64) nth=64;
    size_t nblk64 = (len+63)/64;
    if((size_t)nth > nblk64) nth = nblk64 ? (int)nblk64 : 1;
    job_t jobs[64]; pthread_t th[64];
    size_t per = (nblk64 + nth -1)/nth; /* in 64-byte blocks */
    int used=0;
    for(int i=0;i<nth;i++){
        size_t s = (size_t)i*per*64; if(s>=len && len>0) break;
        size_t e = s + per*64; if(e>len) e=len;
        job_t *j=&jobs[used++];
        j->in=(const unsigned char*)pb.buf+s; j->out=out+s; j->len=e-s;
        memcpy(j->key,key,32); memcpy(j->ctr,ctr,16); j->ctr[0]=(unsigned int)(1+s/64);
        j->rkey=blk0;
        if(len==0) break;
    }
    Py_BEGIN_ALLOW_THREADS
    for(int i=1;i<used;i++) pthread_create(&th[i],NULL,worker,&jobs[i]);
    worker(&jobs[0]);
    for(int i=1;i<used;i++) pthread_join(th[i],NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst = PyList_New(used);
    for(int i=0;i<used;i++){
        PyList_SET_ITEM(lst,i,Py_BuildValue("(KKKn)",(unsigned long long)jobs[i].h[0],(unsigned long long)jobs[i].h[1],(unsigned long long)jobs[i].h[2],(Py_ssize_t)((jobs[i].len+15)/16)));
    }
    PyObject *res = Py_BuildValue("(Ny#N)", ct, (const char*)blk0, (Py_ssize_t)32, lst);
    PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);
    return res;
}

static PyMethodDef M[]={{"encrypt",encrypt,METH_VARARGS,""},{NULL,NULL,0,NULL}};
