#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <stdatomic.h>

extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);

typedef unsigned __int128 u128;
#define M44 0xfffffffffffULL
#define M42 0x3ffffffffffULL
typedef struct { uint64_t v[3]; } fe; /* 44,44,42 limbs, value < ~2^130 partially reduced */

static fe fe_from128(uint64_t lo, uint64_t hi, uint64_t top){ /* value = lo + hi<<64 + top<<128 */
    fe r; r.v[0]=lo&M44; r.v[1]=((lo>>44)|(hi<<20))&M44; r.v[2]=((hi>>24)|(top<<40));
    return r;
}
static fe fe_add(fe a, fe b){ fe r; for(int i=0;i<3;i++) r.v[i]=a.v[i]+b.v[i]; return r; }
static fe fe_mul(fe a, fe b){
    uint64_t r0=b.v[0],r1=b.v[1],r2=b.v[2],s1=r1*20,s2=r2*20;
    uint64_t h0=a.v[0],h1=a.v[1],h2=a.v[2];
    u128 d0=(u128)h0*r0+(u128)h1*s2+(u128)h2*s1;
    u128 d1=(u128)h0*r1+(u128)h1*r0+(u128)h2*s2;
    u128 d2=(u128)h0*r2+(u128)h1*r1+(u128)h2*r0;
    uint64_t c; fe o;
    c=(uint64_t)(d0>>44); o.v[0]=(uint64_t)d0&M44;
    d1+=c; c=(uint64_t)(d1>>44); o.v[1]=(uint64_t)d1&M44;
    d2+=c; c=(uint64_t)(d2>>42); o.v[2]=(uint64_t)d2&M42;
    o.v[0]+=c*5; c=o.v[0]>>44; o.v[0]&=M44; o.v[1]+=c;
    return o;
}
/* fully reduce mod p, return low128 in lo,hi and bits 128..129 in top */
static void fe_final(fe a, uint64_t *lo, uint64_t *hi, uint64_t *top){
    uint64_t h0=a.v[0],h1=a.v[1],h2=a.v[2],c;
    c=h1>>44; h1&=M44; h2+=c; c=h2>>42; h2&=M42; h0+=c*5;
    c=h0>>44; h0&=M44; h1+=c; c=h1>>44; h1&=M44; h2+=c; c=h2>>42; h2&=M42; h0+=c*5;
    c=h0>>44; h0&=M44; h1+=c;
    uint64_t g0=h0+5; c=g0>>44; g0&=M44;
    uint64_t g1=h1+c; c=g1>>44; g1&=M44;
    uint64_t g2=h2+c-(1ULL<<42);
    uint64_t mask=(g2>>63)-1; /* all ones if g2 >= 0 (no borrow) */
    h0=(h0&~mask)|(g0&mask); h1=(h1&~mask)|(g1&mask); h2=(h2&~mask)|(g2&mask);
    *lo = h0 | (h1<<44); *hi = (h1>>20) | (h2<<24); *top = h2>>40;
}
static fe fe_pow(fe b, uint64_t e){
    fe r={{1,0,0}};
    while(e){ if(e&1) r=fe_mul(r,b); b=fe_mul(b,b); e>>=1; }
    return r;
}
static void ld(const unsigned char *p, uint64_t *lo, uint64_t *hi){ memcpy(lo,p,8); memcpy(hi,p+8,8); }

/* ---- thread pool ---- */
#define CHUNK (256*1024)
#define MAXCH 65536
typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    unsigned int key[8]; unsigned int nonce[3];
    unsigned char pk[32];
    size_t nchunks;
    atomic_size_t next;
    unsigned char (*t1)[16];
    unsigned char (*t2)[16];
} work_t;

static work_t W;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER, cv_done = PTHREAD_COND_INITIALIZER;
static int gen=0, active=0, nworkers=0;

static void do_chunks(void){
    _Alignas(64) unsigned char ctx[1024], ctx2[1024];
    size_t cs = Poly1305_ctx_size();
    for(;;){
        size_t i = atomic_fetch_add(&W.next, 1);
        if(i >= W.nchunks) break;
        size_t s = i*(size_t)CHUNK, n = W.len - s; if(n>CHUNK) n=CHUNK;
        unsigned int ctr[4]; ctr[0]=(unsigned int)(1 + s/64); memcpy(ctr+1, W.nonce, 12);
        Poly1305_Init(ctx, W.pk);
        size_t off=0;
        while(off<n){
            size_t m=n-off; if(m>16384) m=16384;
            ChaCha20_ctr32(W.out+s+off, W.in+s+off, m, W.key, ctr);
            size_t full = m & ~(size_t)15;
            Poly1305_Update(ctx, W.out+s+off, full);
            if(full<m){ unsigned char b[16]={0}; memcpy(b,W.out+s+off+full,m-full); Poly1305_Update(ctx,b,16); }
            ctr[0] += (unsigned int)(m/64);
            off+=m;
        }
        memcpy(ctx2, ctx, cs);
        Poly1305_Final(ctx, W.t1[i]);
        unsigned char z[16]={0};
        Poly1305_Update(ctx2, z, 16);
        Poly1305_Final(ctx2, W.t2[i]);
    }
}

static void *worker_main(void *arg){
    (void)arg; int mygen=0;
    for(;;){
        pthread_mutex_lock(&mu);
        while(gen==mygen) pthread_cond_wait(&cv_start,&mu);
        mygen=gen;
        pthread_mutex_unlock(&mu);
        do_chunks();
        pthread_mutex_lock(&mu);
        if(--active==0) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

static void ensure_workers(int n){
    while(nworkers<n){ pthread_t t; pthread_create(&t,NULL,worker_main,NULL); pthread_detach(t); nworkers++; }
}

/* recover h (< p) for chunk from t1 = h mod 2^128, t2 = ((h + 2^128) * r mod p) mod 2^128 */
static fe recover(const unsigned char *t1, const unsigned char *t2, fe r){
    uint64_t lo,hi,a,b; ld(t1,&lo,&hi); ld(t2,&a,&b);
    for(uint64_t top=0; top<4; top++){
        fe c = fe_from128(lo,hi,top);
        fe x = fe_mul(fe_add(c, fe_from128(0,0,1)), r);
        uint64_t xl,xh,xt; fe_final(x,&xl,&xh,&xt);
        if(xl==a && xh==b) return c;
    }
    return fe_from128(lo,hi,0); /* should not happen */
}

static fe poly_bytes(fe acc, fe r, const unsigned char *d, size_t n){
    while(n){
        unsigned char b[16]={0}; size_t m=n<16?n:16; memcpy(b,d,m);
        uint64_t lo,hi; ld(b,&lo,&hi);
        acc = fe_mul(fe_add(acc, fe_from128(lo,hi,1)), r);
        d+=m; n-=m;
    }
    return acc;
}

#define NPOOL 3
static PyObject *pool[NPOOL];
static unsigned char T1[MAXCH][16], T2[MAXCH][16];

